namespace MRS;
internal sealed record FoxFix(double Latitude,double Longitude,DateTimeOffset ReceivedUtc,string Source,double? Altitude=null,double? SpeedKnots=null,double? Course=null,int? Satellites=null,double? Hdop=null,DateTimeOffset? GpsUtc=null)
{
 internal bool Manual=>Source=="Manual stationary";
 internal bool Fresh(DateTimeOffset now)=>double.IsFinite(Latitude)&&double.IsFinite(Longitude)&&Math.Abs(Latitude)<=90&&Math.Abs(Longitude)<=180&&(Manual||now>=ReceivedUtc.AddSeconds(-1)&&now-ReceivedUtc<=TimeSpan.FromSeconds(3));
}
internal sealed class FoxNmea
{
 internal FoxFix? Fix{get;private set;}internal string Status{get;private set;}="Waiting for NMEA RMC/GGA";internal int ValidLines{get;private set;}internal int BadChecksum{get;private set;}
 internal void Clear(string status="Disconnected"){Fix=null;Status=status;}
 internal void Feed(string line,DateTimeOffset received,string source)
 {
  line=line.Trim();if(line.Length<10||line.Length>512||line[0]!='$')return;int star=line.LastIndexOf('*');if(star!=line.Length-3||!byte.TryParse(line.AsSpan(star+1),NumberStyles.HexNumber,CultureInfo.InvariantCulture,out byte expected)){BadChecksum++;return;}byte sum=0;for(int i=1;i<star;i++)sum^=(byte)line[i];if(sum!=expected){BadChecksum++;return;}var f=line[1..star].Split(',');string kind=f[0].Length==5?f[0][2..]:"";if(kind is not ("RMC" or "GGA"))return;ValidLines++;
  try{
   if(kind=="RMC"){
    if(f.Length<10||f[2]!="A"||f.Length>12&&f[12] is "N" or "E" or "S" or "M"){Clear("GPS has no valid fix");return;}double lat=Coordinate(f[3],f[4],true),lon=Coordinate(f[5],f[6],false);DateTimeOffset? utc=null;if(f[9].Length==6&&f[1].Length>=6){int yy=int.Parse(f[9][4..6]);utc=new DateTimeOffset(yy>=80?1900+yy:2000+yy,int.Parse(f[9][2..4]),int.Parse(f[9][..2]),int.Parse(f[1][..2]),int.Parse(f[1][2..4]),Math.Min(59,int.Parse(f[1][4..6])),TimeSpan.Zero);}var previous=Fix;bool adjacent=previous!=null&&received-previous.ReceivedUtc<TimeSpan.FromSeconds(2)&&Distance(previous.Latitude,previous.Longitude,lat,lon)<100;Fix=new(lat,lon,received,source,adjacent?previous!.Altitude:null,Number(f[7]),Number(f[8]),adjacent?previous!.Satellites:null,adjacent?previous!.Hdop:null,utc);Status="GPS fix";
   }else{
    if(f.Length<11||!int.TryParse(f[6],out int quality)||quality is not (1 or 2 or 3 or 4 or 5)){Clear("GPS has no valid fix");return;}double lat=Coordinate(f[2],f[3],true),lon=Coordinate(f[4],f[5],false);var previous=Fix;bool adjacent=previous!=null&&received-previous.ReceivedUtc<TimeSpan.FromSeconds(2)&&Distance(previous.Latitude,previous.Longitude,lat,lon)<100;Fix=new(lat,lon,received,source,f[10]=="M"?Number(f[9],true):null,adjacent?previous!.SpeedKnots:null,adjacent?previous!.Course:null,int.TryParse(f[7],out int sats)?sats:null,Number(f[8]),null);Status="GPS fix · quality "+quality;
   }
  }catch(Exception ex)when(ex is FormatException or ArgumentException or OverflowException){Clear("Invalid GPS fix fields");}
 }
 private static double? Number(string s,bool signed=false)=>double.TryParse(s,NumberStyles.Float,CultureInfo.InvariantCulture,out var v)&&double.IsFinite(v)&&(signed||v>=0)?v:null;
 internal static double Coordinate(string value,string direction,bool latitude){if(!System.Text.RegularExpressions.Regex.IsMatch(value,latitude?@"^[0-9]{4}(\.[0-9]+)?$":@"^[0-9]{5}(\.[0-9]+)?$"))throw new FormatException();if(direction!=(latitude?"N":"E")&&direction!=(latitude?"S":"W"))throw new FormatException();if(!double.TryParse(value,NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out double v)||!double.IsFinite(v)||v<0)throw new FormatException();int deg=(int)(v/100);double minutes=v-deg*100;if(minutes>=60||deg>(latitude?90:180)||deg==(latitude?90:180)&&minutes>0)throw new FormatException();return (deg+minutes/60)*(direction is "S" or "W"?-1:1);}
 internal static double Distance(double lat,double lon,double lat2,double lon2){double a=(lat2-lat)*Math.PI/180,b=(lon2-lon)*Math.PI/180;double h=Math.Pow(Math.Sin(a/2),2)+Math.Cos(lat*Math.PI/180)*Math.Cos(lat2*Math.PI/180)*Math.Pow(Math.Sin(b/2),2);return 12742000*Math.Asin(Math.Sqrt(Math.Clamp(h,0,1)));}
}
internal sealed record FoxScope(string Device,string Backend,long Frequency,string Mode,double FilterHz,int Gain,int Rate,long CaptureHz,double CaptureWidth,double Ppm,int SamplingMode);
internal sealed record FoxReading(DateTimeOffset Utc,FoxScope Scope,double Db,bool SquelchOpen);
internal sealed record FoxPoint(DateTimeOffset Utc,FoxFix Fix,FoxScope Scope,double MeanDb,double PeakDb,int Readings,bool SquelchOpen,double? FloorDb,int Segment)
{
 public string Time=>Utc.ToLocalTime().ToString("HH:mm:ss");public string Position=>$"{Fix.Latitude:F6}, {Fix.Longitude:F6}";public string Signal=>$"{MeanDb:F1}";public string Peak=>$"{PeakDb:F1}";public string AboveFloor=>FloorDb is double n?$"{MeanDb-n:F1}":"—";
}
internal sealed class FoxSignalWindow
{
 private readonly object sync=new();private readonly Queue<FoxReading> rows=[];
 internal void Add(FoxReading r){if(!double.IsFinite(r.Db)||r.Db< -140||r.Db>20)return;lock(sync){rows.Enqueue(r);while(rows.Count>4096)rows.Dequeue();}}
 internal void Clear(){lock(sync)rows.Clear();}
 internal FoxReading[] Recent(DateTimeOffset now,double seconds){lock(sync){while(rows.TryPeek(out var r)&&r.Utc<now.AddSeconds(-Math.Max(3,seconds)))rows.Dequeue();return rows.Where(r=>r.Utc>=now.AddSeconds(-seconds)&&r.Utc<=now.AddSeconds(1)).ToArray();}}
}
internal sealed class FoxSession : IDisposable
{
 internal readonly List<FoxPoint> Points=[];internal FoxScope? Scope{get;private set;}internal string FixSource{get;private set;}="";internal string FilePath{get;private set;}="";internal string CloseError{get;private set;}="";internal bool Running=>writer!=null;private StreamWriter? writer;private int segment;private DateTimeOffset last;
 internal void Start(string path,FoxScope scope,FoxFix fix){if(Running)throw new IOException("Stop the current Fox Hunt first.");if(!fix.Fresh(DateTimeOffset.UtcNow))throw new IOException("A fresh GPS fix or explicit manual position is required.");if(scope.Backend=="RTL"&&scope.Gain== -1000)throw new IOException("Choose fixed RTL RF gain before starting Fox Hunt; automatic gain makes comparisons unreliable.");Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);var stream=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.Read);writer=new StreamWriter(stream,new UTF8Encoding(false)){AutoFlush=true};try{writer.WriteLine("utc,fix_received_utc,gps_utc,latitude,longitude,altitude_m,speed_knots,course_deg,satellites,hdop,position_source,frequency_hz,mode,filter_hz,mean_db_relative,peak_db_relative,readings,squelch_open,noise_floor_db_relative,segment,device,backend,gain_token,sample_rate,capture_hz,capture_width_hz,rx_ppm,sampling_mode");}catch{Dispose();throw;}CloseError="";Points.Clear();Scope=scope;FixSource=fix.Source;FilePath=path;segment=0;last=default;}
 internal FoxPoint? Record(DateTimeOffset now,FoxFix? fix,IReadOnlyList<FoxReading> readings,double? floor=null,bool signalOnly=false)
 {
  if(!Running)return null;if(fix==null||!fix.Fresh(now))return null;if(fix.Source!=FixSource)throw new IOException("Position source changed; stop and start a new Fox Hunt log.");if(readings.Any(r=>r.Scope!=Scope))throw new IOException("Receiver frequency/gain/filter/capture changed; start a new comparable log.");var good=readings.Where(r=>r.Utc<=now.AddSeconds(1)&&now-r.Utc<TimeSpan.FromSeconds(6)&&(!signalOnly||r.SquelchOpen)).ToArray();if(good.Length==0||now-good.Max(r=>r.Utc)>TimeSpan.FromSeconds(2)||signalOnly&&!good.Any(r=>r.SquelchOpen))return null;if(Points.Count>=50000||writer!.BaseStream.Position>=50*1024*1024)throw new IOException("Fox Hunt log limit reached (50,000 points / 50 MB); start a new file.");if(last==default||now-last>TimeSpan.FromSeconds(10))segment++;if(floor is double n&&!double.IsFinite(n))floor=null;double mean=10*Math.Log10(good.Average(r=>Math.Pow(10,r.Db/10)));var point=new FoxPoint(now,fix,Scope!,mean,good.Max(r=>r.Db),good.Length,good.Any(r=>r.SquelchOpen),floor,segment);writer.WriteLine(Csv(point));Points.Add(point);last=now;return point;
 }
 internal static string Csv(FoxPoint p){string N(double? v)=>v?.ToString("R",CultureInfo.InvariantCulture)??"";string I(object? value)=>Convert.ToString(value,CultureInfo.InvariantCulture)??"";return string.Join(',',new[]{p.Utc.ToString("O"),p.Fix.ReceivedUtc.ToString("O"),p.Fix.GpsUtc?.ToString("O")??"",N(p.Fix.Latitude),N(p.Fix.Longitude),N(p.Fix.Altitude),N(p.Fix.SpeedKnots),N(p.Fix.Course),I(p.Fix.Satellites),N(p.Fix.Hdop),p.Fix.Source,I(p.Scope.Frequency),p.Scope.Mode,N(p.Scope.FilterHz),N(p.MeanDb),N(p.PeakDb),I(p.Readings),p.SquelchOpen?"true":"false",N(p.FloorDb),I(p.Segment),p.Scope.Device,p.Scope.Backend,I(p.Scope.Gain),I(p.Scope.Rate),I(p.Scope.CaptureHz),N(p.Scope.CaptureWidth),N(p.Scope.Ppm),I(p.Scope.SamplingMode)}.Select(PlanCsv.Quote));}
 internal static void ExportGpx(string path,IEnumerable<FoxPoint> points){using var stream=new FileStream(path,FileMode.CreateNew,FileAccess.Write);using var x=XmlWriter.Create(stream,new XmlWriterSettings{Indent=true,Encoding=new UTF8Encoding(false)});const string ns="http://www.topografix.com/GPX/1/1",ext="urn:mrs:foxhunt:1";x.WriteStartElement("gpx",ns);x.WriteAttributeString("version","1.1");x.WriteAttributeString("creator","M.R.S. Fox Hunt");x.WriteStartElement("trk",ns);x.WriteElementString("name",ns,"Relative signal measurements — not a transmitter location");int segment= -1;foreach(var p in points){if(p.Segment!=segment){if(segment!=-1)x.WriteEndElement();x.WriteStartElement("trkseg",ns);segment=p.Segment;}x.WriteStartElement("trkpt",ns);x.WriteAttributeString("lat",p.Fix.Latitude.ToString("R",CultureInfo.InvariantCulture));x.WriteAttributeString("lon",p.Fix.Longitude.ToString("R",CultureInfo.InvariantCulture));if(p.Fix.Altitude is double alt)x.WriteElementString("ele",ns,alt.ToString("R",CultureInfo.InvariantCulture));x.WriteElementString("time",ns,p.Utc.UtcDateTime.ToString("O"));x.WriteStartElement("extensions",ns);x.WriteElementString("relativeDb",ext,p.MeanDb.ToString("R",CultureInfo.InvariantCulture));x.WriteElementString("frequencyHz",ext,p.Scope.Frequency.ToString(CultureInfo.InvariantCulture));x.WriteElementString("positionSource",ext,p.Fix.Source);
void E(string key,object? value){if(value!=null)x.WriteElementString(key,ext,Convert.ToString(value,CultureInfo.InvariantCulture));}
E("device",p.Scope.Device);E("backend",p.Scope.Backend);E("gainToken",p.Scope.Gain);E("filterHz",p.Scope.FilterHz);E("sampleRate",p.Scope.Rate);E("captureCenterHz",p.Scope.CaptureHz);E("captureWidthHz",p.Scope.CaptureWidth);E("ppm",p.Scope.Ppm);E("samplingMode",p.Scope.SamplingMode);E("peakRelativeDb",p.PeakDb);E("readings",p.Readings);E("squelchOpen",p.SquelchOpen?"true":"false");E("noiseFloorRelativeDb",p.FloorDb);E("fixReceivedUtc",p.Fix.ReceivedUtc.ToString("O"));E("gpsUtc",p.Fix.GpsUtc?.ToString("O"));E("satellites",p.Fix.Satellites);E("hdop",p.Fix.Hdop);E("speedKnots",p.Fix.SpeedKnots);E("courseDegrees",p.Fix.Course);x.WriteEndElement();x.WriteEndElement();}if(segment!=-1)x.WriteEndElement();x.WriteEndElement();x.WriteEndElement();}
 public void Dispose(){var closing=writer;writer=null;try{closing?.Dispose();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException){CloseError="Log close failed: "+ex.Message;}}
}
